import itertools

def check_counterexample(m, n_set):
    # n_set is a tuple of m distinct positive integers
    n = list(n_set)

    # Condition 1: Sum must NOT be a multiple of m
    sum_n = sum(n)
    if sum_n % m == 0:
        return False  # Not a counterexample

    # Condition 2: For ALL permutations, the weighted sum must NOT be a multiple of m
    # The weights are {1, 2, ..., m}
    weights = list(range(1, m + 1))

    # Iterate over all permutations of indices (which corresponds to assigning weights 1..m to n_1..n_m)
    # We are checking sums: sum_{i=1}^m i * n_{sigma(i)} mod m
    # Since n_set is fixed, we permute the weights (1..m) and apply them to the fixed n_i order.
    # No, this is simpler: we permute the n_i's and fix the weights (1, 2, ..., m).

    is_counterexample_b_holds = True

    # Iterate over all permutations of n
    for p_n in itertools.permutations(n):
        weighted_sum = 0
        for i in range(m):
            # Weight i+1 applied to the i-th element of the permuted set p_n
            weighted_sum += (i + 1) * p_n[i]

        if weighted_sum % m == 0:
            is_counterexample_b_holds = False
            break

    return is_counterexample_b_holds

def find_counterexample(m, max_n=10):
    print(f"--- Testing m = {m} ---")

    # Iterate over all combinations of m distinct integers up to max_n
    for n_tuple in itertools.combinations(range(1, max_n + 1), m):
        if check_counterexample(m, n_tuple):
            return n_tuple

    return None

# Test m from 2 to 8
results = {}
for m in range(2, 9):
    # Adjust max_n based on m for efficiency, but keep a reasonable bound
    max_search = 2 * m + 2 if m <= 4 else 15 
    counterexample = find_counterexample(m, max_search)
    results[m] = counterexample

print("\n--- Summary of Results ---")
for m, ce in results.items():
    if ce:
        print(f"m={m}: Counterexample found: {ce}")
    else:
        print(f"m={m}: No counterexample found within the search limit (max_n={max(ce) if ce else 'N/A'}).")
